[HttpGet]
public async Task<PagedResult<AuditDto>> List(long? after, int pageSize = 50,
    CancellationToken ct = default)
{
    pageSize = Math.Clamp(pageSize, 1, 100);
    var items = await _db.Audit
        .Where(a => after == null || a.Id < after)
        .OrderByDescending(a => a.Id).Take(pageSize + 1)
        .Select(a => new AuditDto(a.Id, a.UserName, a.CreatedAt)).ToListAsync(ct);
    var hasMore = items.Count > pageSize;
    return new(items.Take(pageSize).ToList(), hasMore ? items[pageSize - 1].Id : null);
}

public sealed class LateFeeCalculator(IRentalRepository repo, TimeProvider time)
{
    private const decimal FeePerDay = 2.5m, MaxFee = 100m;

    public async Task<decimal> CalculateAsync(int rentalId, CancellationToken ct)
    {
        var rental = await repo.GetAsync(rentalId, ct);
        var daysLate = (time.GetUtcNow().Date - rental.DueDate.Date).Days;
        return daysLate <= 0 ? 0m : Math.Min(daysLate * FeePerDay, MaxFee);
    }
}

